        w_dec_vld  = (w_reg_wr_addr[5:2] < PARA_USB2_NEP1[3:0]);
        w_dec_slot = (LPARA_B_EPO_CTL[LPARA_SLOT_W-1:0] + {4'd0, w_reg_wr_addr[5:2]});
