      end
      14'b0000011000????: begin
        w_dec_vld  = (w_reg_wr_addr[5:2] < PARA_USB2_NHC[3:0]);
        w_dec_slot = (LPARA_B_HC_CTRL[LPARA_SLOT_W-1:0] + {4'd0, w_reg_wr_addr[5:2]});
