      14'b00000000010000: begin
        w_dec_vld  = 1'b1;
        w_dec_slot = LPARA_B_FIFO_RX[LPARA_SLOT_W-1:0];
      end
      14'b00000000010001: begin
        w_dec_vld  = 1'b1;
        w_dec_slot = LPARA_B_FIFO_HNP[LPARA_SLOT_W-1:0];
      end
      14'b00000000010010: begin
        w_dec_vld  = 1'b1;
        w_dec_slot = LPARA_B_FIFO_HPT[LPARA_SLOT_W-1:0];
      end
      14'b00000000011000: begin
        w_dec_vld  = 1'b1;
        w_dec_slot = LPARA_B_LPM_CFG[LPARA_SLOT_W-1:0];
      end
      14'b0000001011????: begin
        w_dec_vld  = (w_reg_wr_addr[5:2] < PARA_USB2_NEP1[3:0]);
        w_dec_slot = (LPARA_B_EPI_BUF[LPARA_SLOT_W-1:0] + {4'd0, w_reg_wr_addr[5:2]});
      end
      14'b0000001101????: begin
        w_dec_vld  = (w_reg_wr_addr[5:2] < PARA_USB2_NEP1[3:0]);
        w_dec_slot = (LPARA_B_EPI_IEN[LPARA_SLOT_W-1:0] + {4'd0, w_reg_wr_addr[5:2]});
      end
      14'b0000010100????: begin
        w_dec_vld  = (w_reg_wr_addr[5:2] < PARA_USB2_NEP1[3:0]);
        w_dec_slot = (LPARA_B_EPO_IEN[LPARA_SLOT_W-1:0] + {4'd0, w_reg_wr_addr[5:2]});
      end
      14'b0000011001????: begin
        w_dec_vld  = (w_reg_wr_addr[5:2] < PARA_USB2_NHC[3:0]);
        w_dec_slot = (LPARA_B_HC_SPL[LPARA_SLOT_W-1:0] + {4'd0, w_reg_wr_addr[5:2]});
      end
      14'b0000011101????: begin
        w_dec_vld  = (w_reg_wr_addr[5:2] < PARA_USB2_NHC[3:0]);
        w_dec_slot = (LPARA_B_HC_IEN[LPARA_SLOT_W-1:0] + {4'd0, w_reg_wr_addr[5:2]});
      end
      default: begin
        w_dec_vld = 1'b0;
      end
    endcase
  end

  // The command word is the CSR word one cycle after the accepted write (the registers have the
  // new value then); a write while the command FIFO is full is dropped by the crossing.
  always_ff @(posedge i_clk_bus, negedge i_rst_n_bus) begin : p_ff_wr
    if (!i_rst_n_bus) begin
      reg_wr_vld  <= 1'b0;
      reg_wr_slot <= '0;
    end else begin
      reg_wr_vld  <= w_reg_wr_en & w_dec_vld;
      reg_wr_slot <= w_dec_slot;
    end
  end

  assign w_wr_word = w_cfg_all[reg_wr_slot*32 +: 32];

  // Register crossing between CLK-BUS and CLK-PHY.
  m_usb2_xreg #(
    .PARA_USB2_XREG_NS  (LPARA_NS),
    .PARA_USB2_XREG_NA  (LPARA_NA),
    .PARA_USB2_PIPE_XREG (PARA_USB2_PIPE_XREG)
  ) u_xreg (
    .i_clk_bus     (i_clk_bus),
    .i_rst_n_bus   (i_rst_n_bus),
    .i_clk_phy     (i_clk_phy),
    .i_rst_n_phy   (i_rst_n_phy),
    .i_wr_en       (reg_wr_vld),
    .i_wr_slot     (reg_wr_slot),
    .i_wr_word     (w_wr_word),
    .o_xq_free     (w_xq_free),
    .o_xq_ovf      (w_xq_ovf),
    .o_ld_en       (w_ld_en),
    .o_ld_kind     (w_ld_kind),
    .o_ld_slot     (w_ld_slot),
    .o_ld_val      (w_ld_val),
    .i_shadow_init (w_shadow_init),
    .o_shadow      (w_shadow),
    .i_pub         (w_pub_all),
    .i_set         (w_set_all),
    .i_clr         (w_clr_all)
  );

  // Update words of the crossing are registered once and decoded into the hardware loads.
  always_ff @(posedge i_clk_bus, negedge i_rst_n_bus) begin : p_ff_ld
    if (!i_rst_n_bus) begin
      reg_ld_en   <= 1'b0;
      reg_ld_kind <= '0;
      reg_ld_slot <= '0;
      reg_ld_val  <= '0;
    end else begin
      reg_ld_en   <= w_ld_en;
      reg_ld_kind <= w_ld_kind;
      reg_ld_slot <= w_ld_slot;
      reg_ld_val  <= w_ld_val;
    end
  end

  assign w_k_set = reg_ld_en & (reg_ld_kind == LPARA_KIND_SET[3:0]);
  assign w_k_clr = reg_ld_en & (reg_ld_kind == LPARA_KIND_CLR[3:0]);
  assign w_k_pub = reg_ld_en & (reg_ld_kind == LPARA_KIND_PUB[3:0]);

  assign w_hit_sts = (reg_ld_slot == LPARA_B_STS[LPARA_SLOT_W-1:0]);
  assign w_pubhit_sts = w_k_pub & w_hit_sts;
  assign w_hit_dsts = (reg_ld_slot == LPARA_B_DSTS[LPARA_SLOT_W-1:0]);
  assign w_pubhit_dsts = w_k_pub & w_hit_dsts;
  assign w_hit_hsts = (reg_ld_slot == LPARA_B_HSTS[LPARA_SLOT_W-1:0]);
  assign w_pubhit_hsts = w_k_pub & w_hit_hsts;
  assign w_hit_irq_raw = (reg_ld_slot == LPARA_B_IRQ_RAW[LPARA_SLOT_W-1:0]);
  assign w_sethit_irq_raw = w_k_set & w_hit_irq_raw;
  assign w_hit_dctrl = (reg_ld_slot == LPARA_B_DCTRL[LPARA_SLOT_W-1:0]);
  assign w_clrhit_dctrl = w_k_clr & w_hit_dctrl;
  assign w_hit_hport = (reg_ld_slot == LPARA_B_HPORT[LPARA_SLOT_W-1:0]);
  assign w_clrhit_hport = w_k_clr & w_hit_hport;
  assign w_hit_phy_acc = (reg_ld_slot == LPARA_B_PHY_ACC[LPARA_SLOT_W-1:0]);
  assign w_clrhit_phy_acc = w_k_clr & w_hit_phy_acc;
  assign w_pubhit_phy_acc = w_k_pub & w_hit_phy_acc;
  assign w_hit_fifo_ctl = (reg_ld_slot == LPARA_B_FIFO_CTL[LPARA_SLOT_W-1:0]);
  assign w_clrhit_fifo_ctl = w_k_clr & w_hit_fifo_ctl;
  assign w_hit_lpbk_sts = (reg_ld_slot == LPARA_B_LPBK_STS[LPARA_SLOT_W-1:0]);
  assign w_clrhit_lpbk_sts = w_k_clr & w_hit_lpbk_sts;
  assign w_pubhit_lpbk_sts = w_k_pub & w_hit_lpbk_sts;
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NEP1; gen_i++) begin : gen_hit_epi_ctl
      assign w_hit_epi_ctl[gen_i] = (reg_ld_slot == (LPARA_B_EPI_CTL[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_clrhit_epi_ctl[gen_i] = w_k_clr & w_hit_epi_ctl[gen_i];
      assign w_pubhit_epi_ctl[gen_i] = w_k_pub & w_hit_epi_ctl[gen_i];
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NEP1; gen_i++) begin : gen_hit_epi_xfr
      assign w_hit_epi_xfr[gen_i] = (reg_ld_slot == (LPARA_B_EPI_XFR[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_pubhit_epi_xfr[gen_i] = w_k_pub & w_hit_epi_xfr[gen_i];
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NEP1; gen_i++) begin : gen_hit_epi_int
      assign w_hit_epi_int[gen_i] = (reg_ld_slot == (LPARA_B_EPI_INT[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_sethit_epi_int[gen_i] = w_k_set & w_hit_epi_int[gen_i];
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NEP1; gen_i++) begin : gen_hit_epo_ctl
      assign w_hit_epo_ctl[gen_i] = (reg_ld_slot == (LPARA_B_EPO_CTL[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_clrhit_epo_ctl[gen_i] = w_k_clr & w_hit_epo_ctl[gen_i];
      assign w_pubhit_epo_ctl[gen_i] = w_k_pub & w_hit_epo_ctl[gen_i];
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NEP1; gen_i++) begin : gen_hit_epo_xfr
      assign w_hit_epo_xfr[gen_i] = (reg_ld_slot == (LPARA_B_EPO_XFR[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_pubhit_epo_xfr[gen_i] = w_k_pub & w_hit_epo_xfr[gen_i];
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NEP1; gen_i++) begin : gen_hit_epo_int
      assign w_hit_epo_int[gen_i] = (reg_ld_slot == (LPARA_B_EPO_INT[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_sethit_epo_int[gen_i] = w_k_set & w_hit_epo_int[gen_i];
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NHC; gen_i++) begin : gen_hit_hc_ctrl
      assign w_hit_hc_ctrl[gen_i] = (reg_ld_slot == (LPARA_B_HC_CTRL[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_clrhit_hc_ctrl[gen_i] = w_k_clr & w_hit_hc_ctrl[gen_i];
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NHC; gen_i++) begin : gen_hit_hc_xfer
      assign w_hit_hc_xfer[gen_i] = (reg_ld_slot == (LPARA_B_HC_XFER[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_pubhit_hc_xfer[gen_i] = w_k_pub & w_hit_hc_xfer[gen_i];
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NHC; gen_i++) begin : gen_hit_hc_int
      assign w_hit_hc_int[gen_i] = (reg_ld_slot == (LPARA_B_HC_INT[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_sethit_hc_int[gen_i] = w_k_set & w_hit_hc_int[gen_i];
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NHC; gen_i++) begin : gen_hit_hc_cfg
      assign w_hit_hc_cfg[gen_i] = (reg_ld_slot == (LPARA_B_HC_CFG[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
      assign w_pubhit_hc_cfg[gen_i] = w_k_pub & w_hit_hc_cfg[gen_i];
    end
  endgenerate
  assign w_hit_ctrl = (reg_ld_slot == LPARA_B_CTRL[LPARA_SLOT_W-1:0]);
  assign w_hit_sof_cfg = (reg_ld_slot == LPARA_B_SOF_CFG[LPARA_SLOT_W-1:0]);
  assign w_hit_fifo_rx = (reg_ld_slot == LPARA_B_FIFO_RX[LPARA_SLOT_W-1:0]);
  assign w_hit_fifo_hnp = (reg_ld_slot == LPARA_B_FIFO_HNP[LPARA_SLOT_W-1:0]);
  assign w_hit_fifo_hpt = (reg_ld_slot == LPARA_B_FIFO_HPT[LPARA_SLOT_W-1:0]);
  assign w_hit_lpm_cfg = (reg_ld_slot == LPARA_B_LPM_CFG[LPARA_SLOT_W-1:0]);
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NEP1; gen_i++) begin : gen_hit_epi_buf
      assign w_hit_epi_buf[gen_i] = (reg_ld_slot == (LPARA_B_EPI_BUF[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NEP1; gen_i++) begin : gen_hit_epi_ien
      assign w_hit_epi_ien[gen_i] = (reg_ld_slot == (LPARA_B_EPI_IEN[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NEP1; gen_i++) begin : gen_hit_epo_ien
      assign w_hit_epo_ien[gen_i] = (reg_ld_slot == (LPARA_B_EPO_IEN[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NHC; gen_i++) begin : gen_hit_hc_spl
      assign w_hit_hc_spl[gen_i] = (reg_ld_slot == (LPARA_B_HC_SPL[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
    end
  endgenerate
  generate
    for (genvar gen_i = 0; gen_i < PARA_USB2_NHC; gen_i++) begin : gen_hit_hc_ien
      assign w_hit_hc_ien[gen_i] = (reg_ld_slot == (LPARA_B_HC_IEN[LPARA_SLOT_W-1:0] + gen_i[LPARA_SLOT_W-1:0]));
    end
  endgenerate

  // Hold registers of the status fields that the engines publish.
  always_ff @(posedge i_clk_bus, negedge i_rst_n_bus) begin : p_ff_pub
    if (!i_rst_n_bus) begin
      reg_pub_sts_role <= '0;
      reg_pub_sts_speed <= '0;
      reg_pub_sts_attached <= '0;
      reg_pub_sts_suspended <= '0;
      reg_pub_sts_linestate <= '0;
      reg_pub_sts_vbus_valid <= '0;
      reg_pub_sts_id_a_plug <= '0;
      reg_pub_dsts_frame_num <= '0;
      reg_pub_dsts_uframe <= '0;
      reg_pub_dsts_susp_det <= '0;
      reg_pub_dsts_l1_state <= '0;
      reg_pub_dsts_lpm_hird <= '0;
      reg_pub_dsts_lpm_rwake <= '0;
      reg_pub_hsts_port_conn <= '0;
      reg_pub_hsts_port_en <= '0;
      reg_pub_hsts_port_speed <= '0;
      reg_pub_hsts_port_susp_sts <= '0;
      reg_pub_hsts_frame_num <= '0;
      reg_pub_phy_acc_rdata <= '0;
      reg_pub_phy_acc_busy <= '0;
      reg_pub_epi_ctl_active <= '0;
      reg_pub_epi_ctl_nak_sts <= '0;
      reg_pub_epi_ctl_dpid <= '0;
      reg_pub_epi_ctl_buf_cur <= '0;
      reg_pub_epo_ctl_active <= '0;
      reg_pub_epo_ctl_nak_sts <= '0;
      reg_pub_epo_ctl_dpid <= '0;
      reg_pub_epo_ctl_buf_cur <= '0;
      reg_pub_lpbk_sts_pkt_ok <= '0;
      reg_pub_lpbk_sts_pkt_err <= '0;
      reg_pub_hc_cfg_buf_cur <= '0;
    end else begin
      if (w_pubhit_sts)
        reg_pub_sts_role <= reg_ld_val[0];
      if (w_pubhit_sts)
        reg_pub_sts_speed <= reg_ld_val[2:1];
      if (w_pubhit_sts)
        reg_pub_sts_attached <= reg_ld_val[3];
      if (w_pubhit_sts)
        reg_pub_sts_suspended <= reg_ld_val[4];
      if (w_pubhit_sts)
        reg_pub_sts_linestate <= reg_ld_val[6:5];
      if (w_pubhit_sts)
        reg_pub_sts_vbus_valid <= reg_ld_val[7];
      if (w_pubhit_sts)
        reg_pub_sts_id_a_plug <= reg_ld_val[8];
      if (w_pubhit_dsts)
        reg_pub_dsts_frame_num <= reg_ld_val[10:0];
      if (w_pubhit_dsts)
        reg_pub_dsts_uframe <= reg_ld_val[13:11];
      if (w_pubhit_dsts)
        reg_pub_dsts_susp_det <= reg_ld_val[14];
      if (w_pubhit_dsts)
        reg_pub_dsts_l1_state <= reg_ld_val[15];
      if (w_pubhit_dsts)
        reg_pub_dsts_lpm_hird <= reg_ld_val[19:16];
      if (w_pubhit_dsts)
        reg_pub_dsts_lpm_rwake <= reg_ld_val[20];
      if (w_pubhit_hsts)
        reg_pub_hsts_port_conn <= reg_ld_val[0];
      if (w_pubhit_hsts)
        reg_pub_hsts_port_en <= reg_ld_val[1];
      if (w_pubhit_hsts)
        reg_pub_hsts_port_speed <= reg_ld_val[3:2];
      if (w_pubhit_hsts)
        reg_pub_hsts_port_susp_sts <= reg_ld_val[4];
      if (w_pubhit_hsts)
        reg_pub_hsts_frame_num <= reg_ld_val[18:5];
      if (w_pubhit_phy_acc)
        reg_pub_phy_acc_rdata <= reg_ld_val[23:16];
      if (w_pubhit_phy_acc)
        reg_pub_phy_acc_busy <= reg_ld_val[26];
      for (int idx = 0; idx < PARA_USB2_NEP1; idx++) begin
        if (w_pubhit_epi_ctl[idx])
          reg_pub_epi_ctl_active[idx] <= reg_ld_val[14];
      end
      for (int idx = 0; idx < PARA_USB2_NEP1; idx++) begin
        if (w_pubhit_epi_ctl[idx])
          reg_pub_epi_ctl_nak_sts[idx] <= reg_ld_val[15];
      end
      for (int idx = 0; idx < PARA_USB2_NEP1; idx++) begin
        if (w_pubhit_epi_ctl[idx])
          reg_pub_epi_ctl_dpid[idx] <= reg_ld_val[16];
      end
      for (int idx = 0; idx < PARA_USB2_NEP1; idx++) begin
        if (w_pubhit_epi_ctl[idx])
          reg_pub_epi_ctl_buf_cur[idx] <= reg_ld_val[27];
      end
      for (int idx = 0; idx < PARA_USB2_NEP1; idx++) begin
        if (w_pubhit_epo_ctl[idx])
          reg_pub_epo_ctl_active[idx] <= reg_ld_val[14];
      end
      for (int idx = 0; idx < PARA_USB2_NEP1; idx++) begin
        if (w_pubhit_epo_ctl[idx])
          reg_pub_epo_ctl_nak_sts[idx] <= reg_ld_val[15];
      end
      for (int idx = 0; idx < PARA_USB2_NEP1; idx++) begin
        if (w_pubhit_epo_ctl[idx])
          reg_pub_epo_ctl_dpid[idx] <= reg_ld_val[16];
      end
      for (int idx = 0; idx < PARA_USB2_NEP1; idx++) begin
        if (w_pubhit_epo_ctl[idx])
          reg_pub_epo_ctl_buf_cur[idx] <= reg_ld_val[27];
      end
      if (w_pubhit_lpbk_sts)
        reg_pub_lpbk_sts_pkt_ok <= reg_ld_val[11:0];
      if (w_pubhit_lpbk_sts)
        reg_pub_lpbk_sts_pkt_err <= reg_ld_val[23:12];
      for (int idx = 0; idx < PARA_USB2_NHC; idx++) begin
        if (w_pubhit_hc_cfg[idx])
          reg_pub_hc_cfg_buf_cur[idx] <= reg_ld_val[21];
      end
    end
  end

  // Inputs of the CSR: published status, constants of the build and the computed fields.
  assign w_i_version_major = 16'd1;
  assign w_i_version_minor = 16'd0;
  assign w_i_sts_role = reg_pub_sts_role;
  assign w_i_sts_speed = reg_pub_sts_speed;
  assign w_i_sts_attached = reg_pub_sts_attached;
  assign w_i_sts_suspended = reg_pub_sts_suspended;
  assign w_i_sts_linestate = reg_pub_sts_linestate;
  assign w_i_sts_vbus_valid = reg_pub_sts_vbus_valid;
  assign w_i_sts_id_a_plug = reg_pub_sts_id_a_plug;
  assign w_i_sts_rstbusy = i_soft_busy;
  assign w_i_sts_phyclk_ok = i_phy_alive;
  assign w_i_sts_xq_free = w_xq_free;
  assign w_i_build_role_cfg = PARA_USB2_ROLE_CFG[1:0];
  assign w_i_build_phy_ulpi = PARA_USB2_PHY_ULPI[0];
  assign w_i_build_utmi_16 = PARA_USB2_UTMI_16[0];
  assign w_i_build_axi_slave = PARA_USB2_AXI_SLAVE[0];
  assign w_i_build_lpm_cfg = PARA_USB2_LPM_CFG[0];
  assign w_i_build_split_cfg = PARA_USB2_SPLIT_CFG[0];
  assign w_i_build_num_ep = PARA_USB2_NEP1[4:0] - 5'd1;
  assign w_i_build_num_hc = PARA_USB2_NHC[4:0];
  assign w_i_build_fifo_log2 = PARA_USB2_FIFO_LOG2[3:0];
  assign w_i_build_sg_cfg = PARA_USB2_SG_CFG[0];
  assign w_i_build_dbuf_cfg = PARA_USB2_DBUF_CFG[0];
  assign w_i_build_par_cfg = PARA_USB2_PAR_CFG[0];
  assign w_i_irq_sts_sof = w_irq_sts[0];
  assign w_i_irq_sts_busrst = w_irq_sts[1];
  assign w_i_irq_sts_suspend = w_irq_sts[2];
  assign w_i_irq_sts_resume = w_irq_sts[3];
  assign w_i_irq_sts_conn = w_irq_sts[4];
  assign w_i_irq_sts_disc = w_irq_sts[5];
  assign w_i_irq_sts_role_chg = w_irq_sts[6];
  assign w_i_irq_sts_enum = w_irq_sts[7];
  assign w_i_irq_sts_pid_err = w_irq_sts[8];
  assign w_i_irq_sts_crc_err = w_irq_sts[9];
  assign w_i_irq_sts_stuf_err = w_irq_sts[10];
  assign w_i_irq_sts_timeout = w_irq_sts[11];
  assign w_i_irq_sts_babble = w_irq_sts[12];
  assign w_i_irq_sts_fifo_ovf = w_irq_sts[13];
  assign w_i_irq_sts_fifo_udf = w_irq_sts[14];
  assign w_i_irq_sts_axi_err = w_irq_sts[15];
  assign w_i_irq_sts_dma_err = w_irq_sts[16];
  assign w_i_irq_sts_lpm_evt = w_irq_sts[17];
  assign w_i_irq_sts_ep_xfer = w_irq_sts[18];
  assign w_i_irq_sts_hc_xfer = w_irq_sts[19];
  assign w_i_irq_sts_phy_done = w_irq_sts[20];
  assign w_i_irq_sts_iso_inc = w_irq_sts[21];
  assign w_i_irq_sts_ocur = w_irq_sts[22];
  assign w_i_irq_sts_ram_par = w_irq_sts[23];
